BEGIN;
UPDATE public.srd_feats SET srd_source_url=COALESCE(NULLIF(srd_source_url,''),'https://www.d20srd.org/srd/feats.htm'),source_status=CASE WHEN source_status IN ('verified_srd','excluded') THEN source_status ELSE 'source_attached' END,source_notes=COALESCE(NULLIF(source_notes,''),'Catálogo vinculado à página oficial de talentos do SRD; auditoria individual pendente.') WHERE COALESCE(source_status,'')<>'excluded';
UPDATE public.srd_monsters SET srd_source_url=COALESCE(NULLIF(srd_source_url,''),'https://www.d20srd.org/srd/monsters/'),source_status=CASE WHEN source_status IN ('verified_srd','excluded') THEN source_status ELSE 'source_attached' END,source_notes=COALESCE(NULLIF(source_notes,''),'Catálogo vinculado ao índice oficial de monstros do SRD; conferência individual pendente.') WHERE COALESCE(source_status,'')<>'excluded';
UPDATE public.srd_skills SET srd_source_url=COALESCE(NULLIF(srd_source_url,''),'https://www.d20srd.org/srd/skills/skillsSummary.htm'),source_status=CASE WHEN source_status IN ('verified_srd','excluded') THEN source_status ELSE 'source_attached' END,source_notes=COALESCE(NULLIF(source_notes,''),'Catálogo vinculado ao resumo oficial de perícias do SRD; auditoria individual pendente.') WHERE COALESCE(source_status,'')<>'excluded';
UPDATE public.srd_spells SET srd_source_url=COALESCE(NULLIF(srd_source_url,''),'https://www.d20srd.org/srd/spells/'),source_status=CASE WHEN source_status IN ('verified_srd','excluded') THEN source_status ELSE 'source_attached' END,source_notes=COALESCE(NULLIF(source_notes,''),'Catálogo vinculado ao índice oficial de magias do SRD; dados e efeitos ainda precisam de conferência individual.') WHERE COALESCE(source_status,'')<>'excluded';
UPDATE public.srd_conditions SET source_url=COALESCE(NULLIF(source_url,''),'https://www.d20srd.org/srd/conditionSummary.htm') WHERE NULLIF(source_url,'') IS NULL;
UPDATE public.srd_domains SET source_url=COALESCE(NULLIF(source_url,''),'https://www.d20srd.org/srd/variant/magic/domains.htm') WHERE NULLIF(source_url,'') IS NULL;
COMMIT;